/**
 * Single source of truth for the user guide. Rendered three ways:
 *  - the in-app GUIDE overlay (guide.tsx)
 *  - the hover / focus hint strip (hint-bar.tsx), keyed by `data-hint` ids
 *  - GUIDE.md, generated by `bun run guide`
 * Pure data — no browser or React imports, so the Bun script can load it.
 */

export type Row = readonly [name: string, text: string]

export interface Control {
  /** Matches `data-hint` on the element */
  id: string
  name: string
  text: string
}

export interface ControlGroup {
  title: string
  controls: Control[]
}

export interface ScreenGuide {
  mode: string
  name: string
  /** How to get to it */
  open: string
  text: string
  fields: Row[]
  /** F-key label → what it does. Labels are matched against the live LCD for hints. */
  fkeys: Row[]
}

export interface Workflow {
  title: string
  steps: string[]
}

export const QUICK_START: string[] = [
  'Click any pad (or press Z, X, C, V…) — the factory kit is already loaded.',
  'Press PLAY START (or Space). A demo beat plays in Sequence 01; the green column is the playhead.',
  'Click empty cells in the Pattern Sequencer to add hits; click lit cells to remove them. Drag to paint.',
  'Press OVER DUB while playing and tap pads in time — your hits are written into the pattern.',
  'Drag a WAV/MP3 from your computer onto a pad to replace its sound.',
  'Press MODE, then PAD6 (TRIM) to cut the sound, or PAD7 (PROGRAM) to tune and shape it.',
  'Your work autosaves in this browser. MODE → PAD3 (SAVE) exports a project file or a WAV.',
]

