export const CONTROL_HINTS: Record<string, Control> = Object.fromEntries(
  [...PANEL.flatMap((g) => g.controls), ...SEQUENCER].map((c) => [c.id, c]),
)

export function screenGuide(mode: string) {
  return SCREENS.find((s) => s.mode === mode)
}

/** Description for an F-key label on a given screen ("ZOOM4" matches "ZOOM"). */
export function fkeyHelp(mode: string, label: string) {
  const rows = screenGuide(mode)?.fkeys ?? []
  return rows.find(([name]) => label === name || label.startsWith(name))?.[1]
}

export function fieldHelp(mode: string, label: string) {
  const rows = screenGuide(mode)?.fields ?? []
  return rows.find(([name]) => name.split(/\s*\/\s*|\s\(/).includes(label) || name === label)?.[1]
}
